USE cardapio_digital;

ON DUPLICATE KEY UPDATE name = VALUES(name);

SELECT 'Sabor & Mesa', 'Seu momento começa no primeiro sabor.', './assets/logo.png'
WHERE NOT EXISTS (SELECT 1 FROM restaurant_branding);


SELECT c.name AS categoria, COUNT(p.id) AS quantidade
FROM categories c
LEFT JOIN products p ON p.category_id = c.id
GROUP BY c.id, c.name
ORDER BY c.id;
